class Quest:
    def __init__(self, title, description, difficulty="Medium", reward=50, completed=False):
        if not title:
            raise ValueError("Title cannot be empty!")
        if difficulty not in ["Easy", "Medium", "Hard"]:
            raise ValueError("Difficulty must be Easy, Medium, or Hard!")
        if reward < 1:
            raise ValueError("Reward must be positive!")

        self.title = title
        self.description = description
        self.difficulty = difficulty
        self.reward = reward
        self.completed = completed
        print(f"Quest created: {title} ({difficulty}) - Reward: {reward}")

# Create quests
try:
    q1 = Quest("Defeat the Dragon", "Slay the ancient dragon", "Hard", 200)
    q2 = Quest("Rescue the Princess", "Save the princess from the tower", "Medium")
except ValueError as e:
    print(f"Error: {e}")

try:
    q3 = Quest("", "Find the lost ring")
except ValueError as e:
    print(f"Error: {e}")
